def divisors(x):
    div = []
    for j in range(2, int(x ** 0.5) + 1):
        if x % j == 0:
            div += [j, x // j]
    return sorted(set(div))

cnt = 0
for n in range(600001, 10**10):
    d = [x for x in divisors(n) if x % 10 == 7 and x != 7]
    if len(d) > 0:
        print(n, min(d))
        cnt += 1
        if cnt == 5:
            break

